#include "uart_workbench.h"
#include "uart_tool_form.h"
#include "uart_files.h"
#include <cmath>

void UartWorkbench::lock_ui(bool lock){if(ui_locked_==lock)return;ui_locked_=lock;if(lock){dragging_=false;if(::GetCapture()==m_hWnd)::ReleaseCapture();locked_windows_.clear();for(const auto h:{GetSafeHwnd(),commands_.GetSafeHwnd(),instruments_.GetSafeHwnd(),signals_.GetSafeHwnd()})if(::IsWindow(h)){locked_windows_.push_back({h,::IsWindowEnabled(h)!=FALSE});::EnableWindow(h,FALSE);}}else{for(const auto& saved:locked_windows_)if(::IsWindow(saved.first))::EnableWindow(saved.first,saved.second);locked_windows_.clear();}}

bool UartWorkbench::acquire(size_t i,int kind,std::wstring& error){if(shutdown_||tx_reserved(i)||!valid_tx_pacing(pacing_[i])){error=L"Stop the current tool / review TX pacing before starting another operation.";return false;}if(i==0){Request r;r.action=Request::CheckTx;if(!request(r)){error=L"Connect Port A and finish pending TX, automation, file TX and serial controls.";return false;}}else if(!secondary_.connected()||secondary_.tx_busy()){error=L"Connect Port B and finish pending TX first.";return false;}
    auto& run=runs_[i];run.kind=static_cast<decltype(run.kind)>(kind);run.generation=i==0?primary_status_.generation:secondary_.generation();run.id=0;const auto batch=(i==0?*primary_:secondary_.traffic).after(UINT64_MAX,1);run.sequence=batch.newest;run.revision=batch.revision;return true;}
bool UartWorkbench::submit_tool(size_t i,std::string bytes,std::wstring& error,bool unpaced){auto& run=runs_[i];if(run.id||!tx_reserved(i)){error=L"Tool TX already pending or stopped.";return false;}if(i==0){Request r;r.action=Request::SendRaw;r.bytes=std::move(bytes);r.flag=unpaced;const auto id=request(std::move(r));if(id<=0){error=L"Port A TX unavailable; connection/work state changed.";return false;}run.id=static_cast<uint64_t>(id);return true;}return secondary_.submit(std::move(bytes),run.id,error,unpaced);}
bool UartWorkbench::command_send(size_t i,std::string bytes,std::wstring& error){if(!acquire(i,ToolRun::Command,error))return false;if(!submit_tool(i,std::move(bytes),error)){runs_[i].kind=ToolRun::None;return false;}runs_[i].status=L"Command TX pending";return true;}
bool UartWorkbench::start_script(size_t i,std::vector<ScriptStep> steps,std::wstring& error){std::string detail;if(!validate_script(steps,detail)){error=uart_wide(detail);return false;}if(!acquire(i,ToolRun::Script,error))return false;if(!runs_[i].script.start(std::move(steps),runs_[i].generation,GetTickCount64(),detail)){runs_[i].kind=ToolRun::None;error=uart_wide(detail);return false;}return true;}
void UartWorkbench::stop_tool(size_t i){auto& run=runs_[i];if(run.kind==ToolRun::Forward){stop_forwarding("STOPPED by user/close/disconnect; no automatic resume");return;}if(transfers_[i].busy()){transfers_[i].cancel();run.status=L"Cancelling transfer; waiting for owned worker...";return;}if(run.id){if(i==0){Request r;r.action=Request::CancelTx;r.id=run.id;request(r);}else secondary_.cancel(run.id);}if(run.script.active())run.script.cancel("STOPPED by user/close/disconnect; no automatic resume");const bool was_rtu=run.kind==ToolRun::Modbus;rtu_[i].stop("RTU stopped; no automatic resume");run.kind=ToolRun::None;if(was_rtu&&i==0){Request r;r.action=Request::DiscardText;request(r);}run.status=L"Stopped; in-flight bytes may already have affected the target.";}
void UartWorkbench::operation_result(size_t i,const SerialOperationResult& result){auto& run=runs_[i];if(!run.id||run.id!=result.operation.id)return;run.id=0;const bool ok=result.success&&!result.cancelled&&run.generation==result.operation.generation;if(run.kind==ToolRun::Forward){forwarder_.complete(i,ok,result.accepted);if(!forwarder_.active())stop_forwarding(forwarder_.status());}else if(run.kind==ToolRun::Script)run.script.complete(ok,GetTickCount64());else if(run.kind==ToolRun::Modbus)rtu_[i].complete(ok,GetTickCount64());else if(run.kind==ToolRun::Command){run.status=ok?L"Command completed: driver accepted bytes (not a target ACK).":L"Command failed/partial/cancelled; no retry. "+result.error;run.kind=ToolRun::None;commands_.state(i,run.status);}}
void UartWorkbench::poll_tools(){poll_forwarding();const auto now=GetTickCount64();for(size_t i=0;i<2;++i){auto& run=runs_[i];if(run.kind!=ToolRun::None){const bool connected=i==0?primary_status_.connected:secondary_.connected();const auto generation=i==0?primary_status_.generation:secondary_.generation();if(!connected||generation!=run.generation)stop_tool(i);}
        if(run.kind==ToolRun::Transfer){std::wstring result;if(transfers_[i].poll(result)){run.kind=ToolRun::None;run.status=result;groups_[i].save_error=result;if(i==0){Request r;r.action=Request::DiscardText;request(r);}}else run.status=transfers_[i].progress();}
        if(run.kind==ToolRun::Modbus)poll_rtu(i,now);
        if(run.kind==ToolRun::Script){const auto batch=(i==0?*primary_:secondary_.traffic).after(run.sequence,32);if(batch.revision!=run.revision||(!batch.records.empty()&&batch.records.front().sequence>run.sequence+1))run.script.cancel("STOPPED: raw RX history gap; cannot validate expect");
            for(const auto& record:batch.records){run.sequence=record.sequence;if(!record.tx)run.script.receive(record.bytes,record.generation,now);}run.script.tick(now);std::string bytes;if(!run.id&&run.script.next(now,bytes)){std::wstring error;if(!submit_tool(i,std::move(bytes),error))run.script.cancel(message_utf8(error));}
            run.status=uart_wide(run.script.status());const auto& results=run.script.results();for(size_t n=0;n<results.size();++n)run.status+=L"\r\n"+std::to_wstring(n+1)+L". "+uart_wide(results[n]);if(!run.script.active()){if(run.id){if(i==0){Request r;r.action=Request::CancelTx;r.id=run.id;request(r);}else secondary_.cancel(run.id);}run.kind=ToolRun::None;}}
        commands_.state(i,run.status);
    }}
void UartWorkbench::show_commands(){commands_.reports([this](size_t i){return runs_[i].script.csv();});commands_.show(this,ini_,[this](size_t i,std::string bytes,std::wstring& e){return command_send(i,std::move(bytes),e);},[this](size_t i,std::vector<ScriptStep> steps,std::wstring& e){return start_script(i,std::move(steps),e);},[this](size_t i){stop_tool(i);},[this](size_t i){return i==0?primary_status_.generation:secondary_.generation();});}
void UartWorkbench::pacing_dialog(size_t i){const auto current=pacing_[i];UartToolForm form(i?L"Port B TX pacing":L"Port A TX pacing",L"Best-effort Windows/driver pacing for explicit Console, paste, named commands, scripts and file TX. Byte gap: 0..1000 ms; line gap: 0..60000 ms after CR/LF (CRLF counted once within a chunk). File chunk delay remains additional. Protocol transfers/RTU use their own timing. Apply when TX is idle.",{{L"Byte gap (ms)",std::to_wstring(current.byte_ms)},{L"Line gap (ms)",std::to_wstring(current.line_ms)}},{},[](const auto& f,std::wstring& error){double a=0,b=0;if(!uart_number(f[0],0,1000,a)||std::floor(a)!=a||!uart_number(f[1],0,60000,b)||std::floor(b)!=b){error=L"Enter integer byte gap 0..1000 and line gap 0..60000 ms.";return false;}return true;},this);
    if(form.DoModal()!=IDOK||shutdown_)return;Request check;check.action=Request::CheckTx;const bool busy=i==0?(primary_status_.active&&!request(check)):secondary_.tx_busy();if(tx_reserved(i)||busy){warn(L"Finish pending TX / script / automation before applying pacing.");return;}const auto values=form.values();double a=0,b=0;uart_number(values[0],0,1000,a);uart_number(values[1],0,60000,b);const TxPacing selected{static_cast<unsigned>(a),static_cast<unsigned>(b)};const auto section=i?L"Workbench.TX.B":L"Workbench.TX.A";const auto encoded=L"v1:"+std::to_wstring(selected.byte_ms)+L":"+std::to_wstring(selected.line_ms);if(!WritePrivateProfileStringW(section,L"Configuration",encoded.c_str(),ini_.c_str())){warn(L"Cannot save TX pacing; previous settings retained.");return;}pacing_[i]=selected;if(i)secondary_.pacing(selected);}
